package com.hbm.client.gascentrifuge;
import com.hbm.machine.gascentrifuge.*;import java.util.*;import me.shedaniel.math.*;import me.shedaniel.rei.api.client.gui.Renderer;import me.shedaniel.rei.api.client.gui.widgets.*;import me.shedaniel.rei.api.client.plugins.REIClientPlugin;import me.shedaniel.rei.api.client.registry.category.CategoryRegistry;import me.shedaniel.rei.api.client.registry.display.*;import me.shedaniel.rei.api.common.category.CategoryIdentifier;import me.shedaniel.rei.api.common.display.basic.BasicDisplay;import me.shedaniel.rei.api.common.entry.*;import me.shedaniel.rei.api.common.util.EntryStacks;import me.shedaniel.rei.forge.REIPluginClient;import net.minecraft.network.chat.Component;
@REIPluginClient public final class GasCentrifugeReiPlugin implements REIClientPlugin {
 static final CategoryIdentifier<Display> TYPE=CategoryIdentifier.of("hbm","gascentrifuge");@Override public void registerCategories(CategoryRegistry event){event.add(new Category());event.addWorkstations(TYPE,EntryStacks.of(GasCentrifugeContent.ITEM.get()));}@Override public void registerScreens(me.shedaniel.rei.api.client.registry.screen.ScreenRegistry event){event.registerContainerClickArea(new Rectangle(65,25,36,12),GasCentrifugeScreen.class,TYPE);}@Override public void registerDisplays(DisplayRegistry event){for(var recipe:GasCentrifugeRecipes.recipes(event.getRecipeManager()))event.add(new Display(recipe));}
 static final class Display extends BasicDisplay{final GasCentrifugeRecipe recipe;Display(GasCentrifugeRecipe recipe){super(List.of(EntryIngredient.of(EntryStacks.of(recipe.input()))),recipe.results().stream().map(s->EntryIngredient.of(EntryStacks.of(s))).toList());this.recipe=recipe;}@Override public CategoryIdentifier<Display> getCategoryIdentifier(){return TYPE;}}
 static final class Category implements DisplayCategory<Display>{@Override public CategoryIdentifier<Display> getCategoryIdentifier(){return TYPE;}@Override public Component getTitle(){return Component.translatable("container.gasCentrifuge");}@Override public Renderer getIcon(){return EntryStacks.of(GasCentrifugeContent.ITEM.get());}@Override public int getDisplayWidth(Display display){return 166;}@Override public int getDisplayHeight(){return 65;}@Override public List<Widget> setupDisplay(Display display,Rectangle bounds){var widgets=new ArrayList<Widget>();widgets.add(Widgets.createDrawableWidget((g,x,y,partial)->GasCentrifugeViews.draw(display.recipe,g,bounds.x,bounds.y)));widgets.add(Widgets.createSlot(new Point(bounds.x+47,bounds.y+24)).entries(display.getInputEntries().getFirst()).disableBackground().markInput());widgets.add(Widgets.createSlot(new Point(bounds.x+3,bounds.y+42)).entries(GasCentrifugeViews.batteries().stream().map(EntryStacks::of).toList()).disableBackground());for(int i=0;i<display.recipe.results().size();i++){var p=GasCentrifugeViews.output(i);widgets.add(Widgets.createSlot(new Point(bounds.x+p[0],bounds.y+p[1])).entries(display.getOutputEntries().get(i)).disableBackground().markOutput());}return widgets;}}
}
